<?php
require_once __DIR__.'/../includes/core/session.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../classes/identity/AccountSecurity.php';
if(isLoggedIn()){header('Location: ../dashboard/layout.php?page=profile');exit;}
header('Cache-Control: no-store');$_SESSION['recovery_csrf']=$_SESSION['recovery_csrf']??bin2hex(random_bytes(24));$_SESSION['security_binding']=$_SESSION['security_binding']??bin2hex(random_bytes(32));$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['recovery_csrf'],$_POST['csrf']))throw new RuntimeException('Please reload this page and try again.');
 $service=new AccountSecurity((new Database())->getConnection());$action=$_POST['action']??'';
 if($action==='request'){$pending=$service->startRecovery($_POST['identifier']??'',$_SESSION['security_binding'],$_SERVER['REMOTE_ADDR']??'local');$_SESSION['recovery_pending']=['selector'=>$pending['selector']];$_SESSION['recovery_notice']='If an eligible student or examinee account matches, a verification code will be sent to its registered email. The code expires in 10 minutes.';header('Location: forgot_password.php');exit;}
 elseif($action==='verify'){
  if(!isset($_SESSION['recovery_pending']))throw new RuntimeException('Request a code first.');if(($_POST['new_password']??'')!==($_POST['confirm_password']??''))throw new RuntimeException('The passwords do not match.');
  $service->complete($_SESSION['recovery_pending']['selector'],$_SESSION['security_binding'],'password_reset',$_POST['code']??'',null,$_POST['new_password']??'');unset($_SESSION['recovery_pending']);$_SESSION['auth_notice']='Your password has been reset. Sign in with your new password.';session_regenerate_id(true);header('Location: login.php');exit;
 }elseif($action==='restart'){if(isset($_SESSION['recovery_pending']))$service->cancel($_SESSION['recovery_pending']['selector'],$_SESSION['security_binding']);unset($_SESSION['recovery_pending']);header('Location: forgot_password.php');exit;}
 else throw new RuntimeException('Choose a recovery action.');
}catch(Throwable $e){$error=$e instanceof PDOException?'Account recovery is temporarily unavailable. Please try again.':$e->getMessage();}
$notice=$_SESSION['recovery_notice']??'';unset($_SESSION['recovery_notice']);$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recover your account · SRCB Guidance</title><link rel="icon" href="../assets/images/srcblogo.ico"><link rel="stylesheet" href="../assets/css/public-home.css?v=20261029-public"><link rel="stylesheet" href="../assets/css/account-security.css?v=20261029"><link rel="stylesheet" href="../assets/css/account-recovery.css?v=20261029"></head><body class="guidance-home recovery-page"><?php $publicBase='../';require __DIR__.'/../includes/public/header.php';?><main class="recovery-main" id="recoveryMain"><section class="recovery-shell"><aside class="recovery-guide"><span class="recovery-symbol" aria-hidden="true">↗</span><p class="recovery-eyebrow">Let’s get you back in</p><h2>Your account.<br>Your next step.</h2><p>Your school records stay safely with your account while you reset your password.</p><ol><li><span>1</span><div><strong>Find your account</strong><small>Use your registered email or student ID.</small></div></li><li><span>2</span><div><strong>Check your email</strong><small>Enter the six-digit verification code.</small></div></li><li><span>3</span><div><strong>Choose a new password</strong><small>Sign in again when you’re ready.</small></div></li></ol><p class="recovery-help">Can’t access your registered email?<br><strong>Contact the Guidance Office for help.</strong></p></aside><div class="recovery-content"><p class="recovery-progress"><?=empty($_SESSION['recovery_pending'])?'STEP 1 OF 2 · FIND YOUR ACCOUNT':'STEP 2 OF 2 · VERIFY & RESET'?></p><p class="recovery-eyebrow">Account recovery</p><h1>Forgot your password?</h1><p class="recovery-lead">Enter your registered email or student ID. We’ll help you verify your account and set a new password.</p>
<?php if($error):?><p class="ac-error" role="alert"><?=$e($error)?></p><?php endif;?><?php if($notice):?><p class="ac-code-notice" role="status"><?=$e($notice)?></p><?php endif;?>
<?php if(empty($_SESSION['recovery_pending'])):?><form method="post" class="ac-form"><input type="hidden" name="csrf" value="<?=$e($_SESSION['recovery_csrf'])?>"><input type="hidden" name="action" value="request"><label>Registered email or student ID<input id="recovery-identifier" placeholder="Email address or student ID" name="identifier" autocomplete="username" maxlength="100" required></label><button class="ac-primary">Send verification code <span aria-hidden="true">→</span></button></form>
<?php else:?><p class="ac-help">Check your inbox and spam folder. Keep this page open and enter the six-digit code here.</p><form method="post" class="ac-form"><input type="hidden" name="csrf" value="<?=$e($_SESSION['recovery_csrf'])?>"><input type="hidden" name="action" value="verify"><label>Email verification code<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><label>New password<input type="password" name="new_password" autocomplete="new-password" minlength="8" maxlength="72" required><small>Use 8–72 characters.</small></label><label>Confirm new password<input type="password" name="confirm_password" autocomplete="new-password" minlength="8" maxlength="72" required></label><button class="ac-primary">Verify code &amp; reset password</button></form><form method="post" class="ac-restart"><input type="hidden" name="csrf" value="<?=$e($_SESSION['recovery_csrf'])?>"><button class="ac-secondary" name="action" value="restart">Start again / request another code</button><small>Wait at least one minute between requests. Starting again cancels the previous code.</small></form><?php endif;?>
<nav class="recovery-links"><a href="login.php">← Back to sign in</a><a href="register.php">Register as an examinee</a></nav></div></section><p class="recovery-footnote">St. Rita’s College of Balingasag · Guidance Office</p></main><script>document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',event=>{if(form.checkValidity()){const button=event.submitter||form.querySelector('button');if(button){if(button.name&&!form.querySelector('input[type=hidden][name="'+button.name+'"]')){const hidden=document.createElement('input');hidden.type='hidden';hidden.name=button.name;hidden.value=button.value;form.append(hidden);}button.disabled=true;button.textContent='Please wait…';}}}));</script></body></html>